-- HADI June 2026 PART 2: READ ONLY post-commit verification; do not run until PASS from source correction.
WITH ctx AS MATERIALIZED(SELECT set_config('app.current_company_id','1',true) cid),live AS MATERIALIZED(SELECT id,voucher_date FROM vouchers WHERE company_id=(SELECT cid::int FROM ctx) AND deleted_at IS NULL AND optional=false),e AS MATERIALIZED(SELECT id,voucher_id,ledger_account_id,debit_amount,credit_amount FROM voucher_entries WHERE company_id=(SELECT cid::int FROM ctx) AND voucher_id IN(SELECT id FROM live)),june AS MATERIALIZED(SELECT COALESCE(SUM(debit_amount),0) dr,COALESCE(SUM(credit_amount),0) cr FROM e JOIN live v ON v.id=e.voucher_id WHERE e.ledger_account_id=1007 AND v.voucher_date>=DATE '2026-06-01' AND v.voucher_date<DATE '2026-07-01'),balances AS MATERIALIZED(SELECT ledger_account_id,COALESCE(SUM(debit_amount-credit_amount),0) net FROM e WHERE ledger_account_id IN(1007,1021,1022,4282) GROUP BY ledger_account_id),results AS MATERIALIZED(SELECT (SELECT dr FROM june) june_dr,(SELECT cr FROM june) june_cr,(SELECT net FROM balances WHERE ledger_account_id=1007) expense_dr,(SELECT net FROM balances WHERE ledger_account_id=1021) payable_dr,(SELECT net FROM balances WHERE ledger_account_id=1022) prepaid_dr,(SELECT net FROM balances WHERE ledger_account_id=4282) timing_dr,(SELECT COUNT(*) FROM audit_log WHERE company_id=1 AND user_id='system:hadi-june-2026-original-sources-part2-20261110' AND action='repair') audit_rows,(SELECT COUNT(*) FROM voucher_entries e JOIN vouchers v ON v.id=e.voucher_id WHERE e.company_id=1 AND v.company_id=1 AND v.deleted_at IS NULL AND e.voucher_id IN(8571,8574,8577,8580,8583) AND e.ledger_account_id=4282 AND e.debit_amount IN(25000,15000,10000,3000)) prior_period_payment_lines,(SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND id IN(30194,30195) AND ledger_account_id=4282 AND debit_amount=3500) retro_accrual_lines,(SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND voucher_id=17518 AND id IN(61088,61089) AND ((id=61088 AND ledger_account_id=4282 AND debit_amount=1600 AND credit_amount=0) OR(id=61089 AND ledger_account_id=1007 AND credit_amount=1600 AND debit_amount=0))) reduced_journal_lines,(SELECT COUNT(*) FROM vouchers WHERE company_id=1 AND id=17518 AND total_amount=1600 AND deleted_at IS NULL) reduced_header,(SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND id IN(29612,29610,29608,29602,29596) AND ledger_account_id=439 AND debit_amount=0 AND credit_amount IN(30000,18000,6000,12000)) cash_counterparts_preserved)SELECT CASE WHEN june_dr=42550 AND june_cr=1600 AND expense_dr=434350 AND payable_dr=-18000 AND prepaid_dr=7000 AND timing_dr=0 AND audit_rows=7 AND prior_period_payment_lines=5 AND retro_accrual_lines=2 AND reduced_journal_lines=2 AND reduced_header=1 AND cash_counterparts_preserved=5 THEN 'PASS HADI JUNE PART 2' ELSE 'NOT APPLIED OR FAILED - STOP' END verification,resultS.* FROM results;
